import json
import os
import random

random.seed(42)

OAR_OPTIONS = [
    "Both Assertion (A) and Reason (R) are true, and Reason (R) is the correct explanation of Assertion (A).",
    "Both Assertion (A) and Reason (R) are true, but Reason (R) is NOT the correct explanation of Assertion (A).",
    "Assertion (A) is true, but Reason (R) is false.",
    "Assertion (A) is false, but Reason (R) is true."
]

TYPE_LABELS = {
    "OSC": "Single Choice MCQ",
    "OMC": "Multiple Choice MCQ",
    "OTF": "True / False",
    "OAR": "Assertion & Reason",
    "OFB": "Fill in the Blanks",
    "ONE": "Numerical Objective"
}

def make_q(topic_code, q_type, seq, text, options_data, correct_answer, step1, step2, step3, difficulty, vault, blooms="understand"):
    q_code = f"{topic_code}-{q_type}-{seq:03d}"
    sol = f"**Step 1: Conceptual Principle:** {step1}\n\n**Step 2: Detailed Scientific Analysis:** {step2}\n\n**Step 3: Verification & Distractor Analysis:** {step3}"

    formatted_options = []
    extra = {}
    if q_type in ("OSC", "OAR"):
        letters = ["A", "B", "C", "D"]
        for i, opt_text in enumerate(options_data):
            formatted_options.append({
                "id": letters[i],
                "text": opt_text,
                "isCorrect": (letters[i] == correct_answer)
            })
    elif q_type == "OMC":
        letters = ["A", "B", "C", "D"]
        correct_set = set(x.strip() for x in correct_answer.split(","))
        for i, opt_text in enumerate(options_data):
            formatted_options.append({
                "id": letters[i],
                "text": opt_text,
                "isCorrect": (letters[i] in correct_set)
            })
        extra["correctAnswers"] = sorted(list(correct_set))
    elif q_type == "OTF":
        formatted_options = [
            {"id": "A", "text": "True", "isCorrect": (correct_answer == "A")},
            {"id": "B", "text": "False", "isCorrect": (correct_answer == "B")}
        ]
    else:
        formatted_options = []

    q = {
        "questionCode": q_code,
        "topicCode": topic_code,
        "chapterNumber": 9,
        "subjectCode": "SCIT1",
        "boardCode": "MH",
        "board": "Maharashtra Board",
        "subject": "Science and Technology Part - 1",
        "class": "10",
        "type": q_type,
        "text": text,
        "options": formatted_options,
        "correctAnswer": correct_answer,
        "solution": sol,
        "explanation": sol,
        "difficulty": difficulty,
        "vault": vault,
        "marks": 4,
        "estimatedTime": 90 if q_type in ("OMC", "ONE", "OAR") else 60,
        "bloomsTaxonomy": blooms,
        "status": "active"
    }
    q.update(extra)
    return q

def build_subtopic_80(topic_code, osc_items, omc_items, otf_items, oar_items, one_ofb_items):
    """
    Takes:
      osc_items: 44 tuples (text, [4 opts], correct_text, s1, s2, s3, diff)
      omc_items: 10 tuples (text, [4 opts], [correct_texts], s1, s2, s3, diff)
      otf_items: 10 tuples (text, is_true_bool, s1, s2, s3, diff)
      oar_items: 10 tuples (assertion, reason, correct_letter, s1, s2, s3, diff)
      one_ofb_items: 6 tuples (q_type, text, correct_answer, s1, s2, s3, diff)
    Produces 80 questions: 40 exam, 20 practice, 20 foundation.
    """
    assert len(osc_items) == 44, f"{topic_code} OSC len {len(osc_items)}"
    assert len(omc_items) == 10, f"{topic_code} OMC len {len(omc_items)}"
    assert len(otf_items) == 10, f"{topic_code} OTF len {len(otf_items)}"
    assert len(oar_items) == 10, f"{topic_code} OAR len {len(oar_items)}"
    assert len(one_ofb_items) == 6, f"{topic_code} ONE/OFB len {len(one_ofb_items)}"

    # Vault assignment:
    # exam (40): 22 OSC, 5 OMC, 5 OTF, 5 OAR, 3 ONE/OFB
    # practice (20): 11 OSC, 3 OMC, 2 OTF, 3 OAR, 1 ONE/OFB
    # foundation (20): 11 OSC, 2 OMC, 3 OTF, 2 OAR, 2 ONE/OFB
    osc_vaults = ["exam"]*22 + ["practice"]*11 + ["foundation"]*11
    omc_vaults = ["exam"]*5 + ["practice"]*3 + ["foundation"]*2
    otf_vaults = ["exam"]*5 + ["practice"]*2 + ["foundation"]*3
    oar_vaults = ["exam"]*5 + ["practice"]*3 + ["foundation"]*2
    one_vaults = ["exam"]*3 + ["practice"]*1 + ["foundation"]*2

    qs = []
    seq_map = {"OSC": 1, "OMC": 1, "OTF": 1, "OAR": 1, "OFB": 1, "ONE": 1}

    for idx, (text, opts, corr_text, s1, s2, s3, diff) in enumerate(osc_items):
        shuffled = list(opts)
        random.shuffle(shuffled)
        corr_idx = shuffled.index(corr_text)
        corr_letter = ["A", "B", "C", "D"][corr_idx]
        seq = seq_map["OSC"]; seq_map["OSC"] += 1
        qs.append(make_q(topic_code, "OSC", seq, text, shuffled, corr_letter, s1, s2, s3, diff, osc_vaults[idx], "apply" if diff != "easy" else "understand"))

    for idx, (text, opts, corr_texts, s1, s2, s3, diff) in enumerate(omc_items):
        shuffled = list(opts)
        random.shuffle(shuffled)
        corr_letters = [ ["A", "B", "C", "D"][shuffled.index(ct)] for ct in corr_texts ]
        corr_letters.sort()
        seq = seq_map["OMC"]; seq_map["OMC"] += 1
        qs.append(make_q(topic_code, "OMC", seq, text, shuffled, ", ".join(corr_letters), s1, s2, s3, diff, omc_vaults[idx], "analyze"))

    for idx, (text, is_true, s1, s2, s3, diff) in enumerate(otf_items):
        corr_letter = "A" if is_true else "B"
        seq = seq_map["OTF"]; seq_map["OTF"] += 1
        qs.append(make_q(topic_code, "OTF", seq, text, ["True", "False"], corr_letter, s1, s2, s3, diff, otf_vaults[idx], "understand"))

    for idx, (assertion, reason, corr_letter, s1, s2, s3, diff) in enumerate(oar_items):
        text = f"**Assertion (A):** {assertion}\n\n**Reason (R):** {reason}"
        seq = seq_map["OAR"]; seq_map["OAR"] += 1
        qs.append(make_q(topic_code, "OAR", seq, text, OAR_OPTIONS, corr_letter, s1, s2, s3, diff, oar_vaults[idx], "analyze"))

    for idx, (qt, text, corr_ans, s1, s2, s3, diff) in enumerate(one_ofb_items):
        seq = seq_map[qt]; seq_map[qt] += 1
        qs.append(make_q(topic_code, qt, seq, text, [], str(corr_ans), s1, s2, s3, diff, one_vaults[idx], "apply"))

    return qs

